class Solution {
    public boolean checkInclusion(String s1, String s2) {
        if (s1.length() > s2.length()) return false;

        int[] s1Count = new int[26];
        int[] windowCount = new int[26];

        // Build s1 frequency map
        for (char c : s1.toCharArray()) {
            s1Count[c - 'a']++;
        }

        int windowSize = s1.length();

        for (int i = 0; i < s2.length(); i++) {
            // Add current character
            windowCount[s2.charAt(i) - 'a']++;

            // Remove character leaving window
            if (i >= windowSize) {
                windowCount[s2.charAt(i - windowSize) - 'a']--;
            }

            // Check if frequencies match
            if (java.util.Arrays.equals(s1Count, windowCount)) {
                return true;
            }
        }

        return false;
    }
}

class Solution {
    public boolean checkInclusion(String s1, String s2) {
        if (s1.length() > s2.length()) return false;

        int[] s1Count = new int[26];
        int[] s2Count = new int[26];

        for (char c : s1.toCharArray()) {
            s1Count[c - 'a']++;
        }

        int matches = 0;
        int windowSize = s1.length();

        // Initialize: count matches for empty s2Count
        for (int i = 0; i < 26; i++) {
            if (s1Count[i] == 0) matches++;
        }

        for (int i = 0; i < s2.length(); i++) {
            // Add character to window
            int idx = s2.charAt(i) - 'a';
            s2Count[idx]++;
            if (s2Count[idx] == s1Count[idx]) matches++;
            else if (s2Count[idx] == s1Count[idx] + 1) matches--;

            // Remove character leaving window
            if (i >= windowSize) {
                int leftIdx = s2.charAt(i - windowSize) - 'a';
                s2Count[leftIdx]--;
                if (s2Count[leftIdx] == s1Count[leftIdx]) matches++;
                else if (s2Count[leftIdx] == s1Count[leftIdx] - 1) matches--;
            }

            if (matches == 26) return true;
        }

        return false;
    }
}

class Solution {
    public boolean checkInclusion(String s1, String s2) {
        if (s1.length() > s2.length()) return false;

        int[] need = new int[26];
        for (int i = 0; i < s1.length(); i++) {
            need[s1.charAt(i) - 'a']++;
        }

        int missing = s1.length();
        int windowSize = s1.length();

        for (int right = 0; right < s2.length(); right++) {
            int in = s2.charAt(right) - 'a';
            if (need[in] > 0) {
                missing--;
            }
            need[in]--;

            if (right >= windowSize) {
                int out = s2.charAt(right - windowSize) - 'a';
                need[out]++;
                if (need[out] > 0) {
                    missing++;
                }
            }

            if (missing == 0) {
                return true;
            }
        }

        return false;
    }
}

import java.util.Arrays;

class Solution {
    public boolean checkInclusion(String s1, String s2) {
        int patternLength = s1.length();
        if (patternLength > s2.length()) {
            return false;
        }

        char[] sortedPattern = s1.toCharArray();
        Arrays.sort(sortedPattern);

        for (int start = 0; start + patternLength <= s2.length(); start++) {
            char[] window = s2.substring(start, start + patternLength).toCharArray();
            Arrays.sort(window);
            if (Arrays.equals(sortedPattern, window)) {
                return true;
            }
        }

        return false;
    }
}
